278: func (s *Server) collectRetiredForScope(ctx context.Context, scope string) ([]dossiers.Entry, error) {
279: 	seen := make(map[string]bool)
280: 	var result []dossiers.Entry
281: 
282: 	entries, err := s.idx.ListEntriesByScope(ctx, scope)
283: 	if err == nil {
284: 		for _, e := range entries {
285: 			if e.Retired || e.RetiredReason != "" || e.SupersededBy != "" {
286: 				if !seen[e.ID] {
287: 					seen[e.ID] = true
288: 					result = append(result, e)
289: 				}
290: 			}
291: 			hists, err := s.idx.GetHistory(ctx, e.ID)
292: 			if err == nil {
293: 				for _, h := range hists {
294: 					key := h.ID + ":" + h.RetiredReason + ":" + h.SupersededBy
295: 					if !seen[key] && !seen[h.ID] {
296: 						seen[key] = true
297: 						result = append(result, h)
298: 					}
299: 				}
300: 			}
301: 		}
302: 	}
303: 
304: 	_ = s.idx.WriteTx(ctx, func(tx *sql.Tx) error {
305: 		rows, err := tx.QueryContext(ctx,
306: 			`SELECT entry_id, type, dossier_scope, text, reason, superseded_by, retired_at
307: 			 FROM entry_history
308: 			 WHERE dossier_scope = ?
309: 			 ORDER BY retired_at DESC`, scope)
310: 		if err != nil {
311: 			return err
312: 		}
313: 		defer rows.Close()
