315: 		for rows.Next() {
316: 			var eID, typeStr, dScope, text, reason, supersededBy, retiredAt sql.NullString
317: 			if err := rows.Scan(&eID, &typeStr, &dScope, &text, &reason, &supersededBy, &retiredAt); err == nil {
318: 				key := eID.String + ":" + reason.String + ":" + supersededBy.String
319: 				if !seen[key] && !seen[eID.String] {
320: 					seen[key] = true
321: 					result = append(result, dossiers.Entry{
322: 						ID:            eID.String,
323: 						Type:          dossiers.EntryType(typeStr.String),
324: 						DossierScope:  dScope.String,
325: 						Text:          text.String,
326: 						Retired:       true,
327: 						RetiredReason: reason.String,
328: 						SupersededBy:  supersededBy.String,
329: 					})
330: 				}
331: 			}
332: 		}
333: 		return rows.Err()
334: 	})
335: 
336: 	return result, nil
337: }
